// std::sregex_iterator: Efficient Match Retrieval

const std::string text = "A1 B2 C3";
const std::regex pattern(R"([A-Z]\d)");

// Iterator definition: Begin and End
using MatchIter = std::sregex_iterator;
MatchIter current(text.begin(), text.end(), pattern);
MatchIter end;

// Iterating and accessing matches (std::smatch objects)
while (current != end) {
    std::string match_str = current->str(); // Access full match
    // std::cout << match_str << "\n";
    ++current;
}

